std::vector<std::uint8_t> PayloadBytes(const std::vector<std::uint8_t>&g,std::size_t n){return {g.begin()+kGuardBytes,g.begin()+kGuardBytes+n};}
std::vector<std::uint8_t> Join(std::initializer_list<std::vector<std::uint8_t>>xs){std::vector<std::uint8_t>r;for(auto&x:xs)r.insert(r.end(),x.begin(),x.end());return r;}
void Restore(GpuContext&g,GpuBuffer&b,D3D12_RESOURCE_STATES state){Transition(g.list.Get(),b.resource.Get(),b.state,state);b.state=state;}
void Restore(GpuContext&g,GpuTexture&t,D3D12_RESOURCE_STATES state){Transition(g.list.Get(),t.resource.Get(),t.state,state);t.state=state;}
